 sid=run['scenario_id'];k=sid[:3]; cap=ts[sid]; msgs=cap['visible_assistant_messages'];assert cap['final_answer']==run['actual_answer'];assert hashlib.sha256(run['actual_answer'].encode()).hexdigest()==run['answer_sha256']
