res={'kind':'ADDITIVE_HISTORICAL_REJUDGMENT_NOT_FRESH_ACCEPTANCE','contract_version':'1.0.1','contract_sha256':hashlib.sha256(contract.read_bytes()).hexdigest(),'reviewer':'/root/rejudge_presentation_101','independent':True,'reviewed_at':datetime.datetime.now(datetime.timezone.utc).isoformat(),'old_artifacts_modified':False,'scope':'All selected historical assistant captures including commentary and raw metadata, B10 selected retest only. No new conversations. Existing results remain unchanged.','raw_ui_limits':'NO_INTERNALS assesses raw captured output. Memory-citation rendering in actual UI is not verified. Current presentation exception only exempts mandatory minimum progress/skill announcements, not metadata.','source_checks':['Original procedural guide printed184/185 rendered and visually inspected','Original behavior regulations printed50/51 (physical49/50) rendered and visually inspected','Current guide/workflow.md, context/decisions.md DEC-003/007/012/016, work/register.json read','B02 high-stakes source facts relied on independently documented historical verification; no new medical recommendation or temporal web-source validation in rejudgment'],'source_run_file_sha256':hashlib.sha256((p/'actual_runs_reviewed.json').read_bytes()).hexdigest(),'results':results,'summary':{'pass':sum(x['status']=='PASS' for x in results),'fail':sum(x['status']=='FAIL' for x in results),'professional_pass':sum(x['professional_status']=='PASS' for x in results),'professional_fail':sum(x['professional_status']=='FAIL' for x in results),'old_summary':{'pass':5,'fail':12},'scenario_result_changes':[]}}
